import{_ as t,o,c as a,ag as c}from"./chunks/framework.D9ghT4bC.js";const h=JSON.parse('{"title":"多人游戏","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Other/Multiplayer.md","filePath":"zh/Other/Multiplayer.md"}'),l={name:"zh/Other/Multiplayer.md"};function i(r,e,d,n,s,p){return o(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="多人游戏" tabindex="-1">多人游戏 <a class="header-anchor" href="#多人游戏" aria-label="Permalink to &quot;多人游戏&quot;">​</a></h1><p>UncivCN 在线联机统一连接社区运营的闭源 Go 服务器（UncivSrv），地址固定为 <code>https://unciv.civgo.top:30123</code>。其他服务器上的对局不会自动迁移。</p><h2 id="如何游玩" tabindex="-1">如何游玩 <a class="header-anchor" href="#如何游玩" aria-label="Permalink to &quot;如何游玩&quot;">​</a></h2><ol start="0"><li>在 <code>主菜单 -&gt; 选项 -&gt; 多人游戏</code> 中点击 <code>检测连接</code>。</li><li>让所有玩家把他们的用户 ID 发给你（<code>主菜单 -&gt; 多人游戏 -&gt; 复制用户 ID</code>）。 <ul><li>（可选）把这些用户 ID 加入你的好友列表（<code>主菜单 -&gt; 多人游戏 -&gt; 好友列表</code>）。</li></ul></li><li>在 <code>主菜单 -&gt; 开始新游戏</code> 中，勾选左侧的 <code>在线多人游戏</code>。在右侧添加更多人类玩家，输入你想一起玩的玩家的用户 ID。点击 <code>开始游戏！</code>。</li><li>游戏 ID 会自动复制到你的剪贴板。（如果弄丢了，可以从 <code>主菜单 -&gt; 多人游戏 -&gt; 复制游戏 ID</code> 重新获取。）把这个游戏 ID 发给其他玩家。</li><li>其他玩家需要进入 <code>主菜单 -&gt; 多人游戏 -&gt; 添加多人游戏</code>，输入你发给他们的游戏 ID。然后他们就可以从多人游戏界面加入游戏了。</li></ol><p>房主开启重开投票后，仍存活的玩家可在指定回合从局内菜单发起投票。存活玩家全部投票或到达截止时间时结算；超时未投票视为同意，票数平局也通过。UncivSrv 会在玩家重连或服务端重启后保留投票状态。投票通过后按原配置创建新局。</p>',5)])])}const u=t(l,[["render",i]]);export{h as __pageData,u as default};
